{%- comment -%} Badges widget: only on products tagged "show_badge" {%- endcomment -%}
<style class="jalg-badge-rule">
  /* this Custom Liquid block itself takes no space */
  .product-block:has(> .jalg-badge-rule) { display: none; }
  {%- unless product.tags contains 'show_badge' %}
  .shopify-block:has(.GSC-UGiaDeWRobMJjsm),
  .GSC-UGiaDeWRobMJjsm { display: none !important; }
  {%- endunless %}
</style>

{% assign brackets = all_products['shelf-brackets'] %}
<div class="jalg-value">
  <div class="jalg-value__top">
    <strong>Included with every JALG TV stand</strong>
    {% if brackets != blank %}
      <a href="{{ routes.root_url | append: '/products/shelf-brackets' | replace: '//', '/' }}" target="_blank" rel="noopener noreferrer" aria-label="View brackets (opens in a new tab)"><span>value</span> <span translate="no">{{ brackets.price | money }}</span></a>
    {% endif %}
  </div>
  <p>Brackets for a soundbar or shelving plate.<br>More mounting possibilities at no extra cost.</p>
</div>

<style>
.jalg-value{padding:18px 20px;background:#3d56400d;border-left:2px solid #3d5640}
.jalg-value__top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;color:#3d5640}
.jalg-value__top strong{font-size:15px;font-weight:600}
.jalg-value__top a{display:inline-block;padding:7px 8px 7px 10px;background:#FF4F33;color:#fff;border:0;font-family:var(--typeBasePrimary),var(--typeBaseFallback);font-size:12px;font-weight:var(--typeBaseWeight);line-height:1;letter-spacing:.2em;text-transform:uppercase;text-decoration:none;white-space:nowrap}
.jalg-value__top a:hover{background:#d93820;color:#fff}
.jalg-value__top a:focus-visible{outline:2px solid #3d5640;outline-offset:3px}
.jalg-value p{margin:10px 0 0;font-size:14px;line-height:1.6}
@media(max-width:589px){.jalg-value__top a{font-size:10px;padding:6px 6px 6px 8px}}
</style>

{% if product.tags contains 'stainless_steel' %}
  {% assign wheels = all_products['stainless-steel-wheels'] %}
  <p id="wheels-note" style="margin:4px 0 14px; font-size:0.85em; line-height:1.4;">
    <strong>Wheels not included. Add the matching set below.</strong>
  </p>
  <script>
    document.addEventListener('DOMContentLoaded', function () {
      var note = document.getElementById('wheels-note');
      var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      while (walker.nextNode()) {
        if (walker.currentNode.nodeValue.trim().toUpperCase().indexOf('TAX INFORMATION') === 0) {
          var el = walker.currentNode.parentElement;
          while (['STRONG','B','SPAN','EM','SMALL'].indexOf(el.tagName) > -1) el = el.parentElement;
          el.parentNode.insertBefore(note, el);
          break;
        }
      }
    });
  </script>
{% endif %}

{% comment %}Hide incoming stock status for tagged products{% endcomment %}
{% if product.tags contains 'hide_incoming' %}
<style>
.product-section[data-product-id="{{ product.id }}"] [data-incoming-inventory]{
  display:none!important;
}
</style>
{% endif %}
